private void Apply(float blend)
{
    playerCamera.fieldOfView = Mathf.Lerp(normalFov, aimFov, blend);

    weaponSway?.SetAimBlend(blend);      // dampens sway while aiming
    playerMovement?.SetAimBlend(blend);  // slows movement while aiming
}

// Reserve ammo lives in the grid inventory when one is linked (quest
// scenes) or in a plain counter elsewhere — same gun code either way.
public int ReserveAmmo => (inventoryGrid != null && ammoItemData != null)
    ? inventoryGrid.CountAmmoOfType(ammoItemData) * BulletsPerMag
    : reserveAmmo;

public bool TryConsume()
{
    if (currentInMag <= 0) return false;
    currentInMag--;
    onAmmoChanged.Invoke(currentInMag, ReserveAmmo);
    return true;
}

public void Reload()
{
    int reserve = ReserveAmmo;
    if (IsFull || reserve <= 0) return;

    if (inventoryGrid != null && ammoItemData != null)
    {
        // Each inventory item = 1 full mag: consume the item, fresh mag
        inventoryGrid.ConsumeAmmoOfType(ammoItemData, 1);
        currentInMag = magazineSize;
    }
    else
    {
        int loaded = Mathf.Min(magazineSize - currentInMag, reserve);
        currentInMag += loaded;
        reserveAmmo -= loaded;
    }

    onAmmoChanged.Invoke(currentInMag, ReserveAmmo);
}

