// Manager: assets stay read-only, per-quest progress lives here
public void ReportEnemyKilled()
{
    for (int q = 0; q < quests.Length; q++)
    {
        if (quests[q] == null || _questDone[q]) continue;

        var objectives = quests[q].objectives;
        for (int i = 0; i < objectives.Length; i++)
        {
            if (objectives[i].type != SennaObjectiveType.KillEnemy) continue;
            if (_progress[q][i] >= objectives[i].requiredCount) continue;
            _progress[q][i]++;
        }

        if (IsQuestComplete(q)) CompleteQuest(q);
    }
}

// Side-mission loot: one weighted roll from the quest's pool
private SennaRewardEntry PickReward(SennaRewardEntry[] pool)
{
    int total = 0;
    foreach (var e in pool) total += Mathf.Max(1, e.weight);

    int roll = Random.Range(0, total);
    int cumulative = 0;
    foreach (var e in pool)
    {
        cumulative += Mathf.Max(1, e.weight);
        if (roll < cumulative) return e;
    }
    return pool[pool.Length - 1];
}

