public static void SetupQuestsScene()
{
    // Idempotent: every step checks for existing objects first,
    // so anyone on the team can run it safely at any time
    var player   = FindOrInstantiate("MainPlayer", PlayerPrefabPath, spawn);
    var canvasGO = FindOrInstantiate("UICanvas", CanvasPrefabPath, Vector3.zero);
    var gsmGO    = FindOrInstantiate("GameStateManager", GsmPrefabPath, Vector3.zero);

    // Wire private [SerializeField] references the way the inspector would
    var so = new SerializedObject(gsmGO.GetComponent<GameStateManager>());
    so.FindProperty("startPanel").objectReferenceValue = FindChild(canvasGO, "StartPanel");
    so.FindProperty("deathPanel").objectReferenceValue = FindChild(canvasGO, "DeathPanel");
    so.FindProperty("playerMovement").objectReferenceValue =
        player.GetComponentInChildren<SennaPlayerMovement>(true);
    so.ApplyModifiedProperties();

    // Missing quest assets are created on the spot
    var q1 = LoadOrCreateQuest("Q1_SituationReport", q =>
    {
        q.questName   = "Situation Report";
        q.isMainQuest = true;
        q.objectives  = new[] { new SennaQuestObjective {
            type = SennaObjectiveType.CollectItem,
            targetItem = briefingItem, requiredCount = 1 } };
    });

    Undo.RegisterCreatedObjectUndo(player, "Setup Quests Scene");
}

private void CheckForWalls()
{
    isWallSliding = false;

    // Check left and right for wall collision
    bool rightWall = Physics2D.Raycast(transform.position, Vector2.right, wallCheckDistance, wallLayer);
    bool leftWall = Physics2D.Raycast(transform.position, Vector2.left, wallCheckDistance, wallLayer);

    if ((rightWall || leftWall) && !isGrounded && rb.velocity.y < 0)
    {
        isWallSliding = true;
        wallDir = rightWall ? 1 : -1;
    }
}

public void WallJump()
{
    if (isWallSliding)
    {
        // Apply force in opposite direction of wall
        Vector2 force = new Vector2(-wallDir * wallJumpForce.x, wallJumpForce.y);
        rb.velocity = Vector2.zero; // Reset momentum
        rb.AddForce(force, ForceMode2D.Impulse);

        StartCoroutine(DisableMovement(0.15f)); // Brief lock
    }
}

